insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$361e0a4e-1890-539c-94d2-6810bbfbd22c$few$, $few$tilapia$few$, $few$Tilapia$few$, array[$few$frozen tilapia$few$]::text[], $few$frozen, then cooked until opaque$few$, $few$okay_if_prepared$few$::public.safety_verdict, $few$FDA lists tilapia as a Best Choice. During pregnancy or breastfeeding, eat 2 to 3 servings a week from the Best Choices list. A serving is 4 ounces. Cook seafood to 145°F (63°C).$few$, $few$Cook tilapia to 145°F (63°C), until it is opaque.$few$, $few$FDA: Advice about Eating Fish; cook temperature from FoodSafety.gov$few$, $few$https://www.fda.gov/food/consumers/advice-about-eating-fish$few$);
