insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$b00f6f69-6257-5bd4-9c73-39254c385b65$few$, $few$cheese$few$, $few$Cheese$few$, '{}'::text[], null, $few$okay_if_prepared$few$::public.safety_verdict, $few$Avoid cheese made with unpasteurized milk, and avoid unheated queso fresco-type cheeses. Hard cheeses such as cheddar, Parmesan, and Swiss are listed when made with pasteurized milk. Cottage cheese, cream cheese, feta, and mozzarella are listed when made with pasteurized milk.$few$, $few$Check the label for pasteurized milk. Heat queso fresco-type cheese to 165°F or until steaming hot.$few$, $few$FoodSafety.gov: People at Risk: Pregnant Women$few$, $few$https://www.foodsafety.gov/risk/pregnant$few$);
insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$0add6afa-03ad-551a-b23c-bb8b1410503d$few$, $few$canned-tuna$few$, $few$Canned tuna$few$, array[$few$tuna$few$]::text[], $few$canned; the ingredient list says low-mercury varieties$few$, $few$okay_if_prepared$few$::public.safety_verdict, $few$FDA lists canned light tuna, including skipjack, as a Best Choice: 2 to 3 servings a week. Albacore or white tuna, canned or fresh, is a Good Choice: one serving that week and no other fish.$few$, $few$Choose canned light tuna. If the can says albacore or white tuna, eat only one 4-ounce serving that week and no other fish.$few$, $few$FDA: Advice about Eating Fish$few$, $few$https://www.fda.gov/food/consumers/advice-about-eating-fish$few$);
insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$bcf40894-8d02-5b5f-8e76-91fc2436636d$few$, $few$canned-salmon$few$, $few$Canned salmon$few$, array[$few$salmon$few$]::text[], $few$canned$few$, $few$okay$few$::public.safety_verdict, $few$FDA lists salmon as a Best Choice. During pregnancy or breastfeeding, eat 2 to 3 servings a week from the Best Choices list. A serving is 4 ounces.$few$, null, $few$FDA: Advice about Eating Fish$few$, $few$https://www.fda.gov/food/consumers/advice-about-eating-fish$few$);
