insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$c23c30fc-8b87-5736-9e10-cb0c1785b6cc$few$, $few$alcohol$few$, $few$Alcohol$few$, array[$few$wine$few$,$few$beer$few$,$few$liquor$few$,$few$red wine$few$,$few$white wine$few$,$few$vodka$few$,$few$rum$few$,$few$whiskey$few$,$few$bourbon$few$]::text[], null, $few$avoid$few$::public.safety_verdict, $few$There is no known safe amount of alcohol during pregnancy, no safe time to drink, and all types can be harmful, including wine, beer, and liquor.$few$, $few$Do not drink alcohol during pregnancy.$few$, $few$CDC: About Alcohol Use During Pregnancy$few$, $few$https://www.cdc.gov/alcohol-pregnancy/about/index.html$few$);
insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$e8e972a5-060f-5a3b-859d-3c3107eb6e22$few$, $few$caffeine$few$, $few$Caffeine$few$, array[$few$coffee$few$,$few$tea$few$,$few$energy drink$few$,$few$espresso$few$,$few$soft drink$few$]::text[], null, $few$limit$few$::public.safety_verdict, $few$ACOG says moderate caffeine, less than 200 milligrams a day, has not been shown to cause miscarriage or preterm birth. That is about one 12-ounce cup of coffee. Caffeine is also in tea, chocolate, energy drinks, and soft drinks.$few$, $few$Keep total caffeine from all sources under 200 milligrams a day.$few$, $few$ACOG: How much coffee can I drink while I'm pregnant?$few$, $few$https://www.acog.org/womens-health/experts-and-stories/ask-acog/how-much-coffee-can-i-drink-while-pregnant$few$);
insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$31626a12-67eb-535c-9097-5136e3a685d8$few$, $few$raw-fish$few$, $few$Raw fish$few$, array[$few$sushi$few$,$few$sashimi$few$,$few$raw oysters$few$,$few$raw oyster$few$,$few$raw clams$few$,$few$raw scallops$few$,$few$ceviche$few$]::text[], $few$raw$few$, $few$avoid$few$::public.safety_verdict, $few$Raw seafood may contain parasites or germs, including Listeria. Cook seafood to 145°F (63°C). Avoid raw sushi, sashimi, raw oysters, raw clams, raw scallops, and ceviche.$few$, $few$Cook seafood to 145°F (63°C).$few$, $few$FoodSafety.gov: People at Risk: Pregnant Women$few$, $few$https://www.foodsafety.gov/risk/pregnant$few$);
insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$25699b3e-df32-5858-8fbe-18785e22851c$few$, $few$deli-meat$few$, $few$Deli meat$few$, array[$few$lunch meat$few$,$few$luncheon meat$few$,$few$cold cuts$few$,$few$hot dog$few$,$few$hot dogs$few$,$few$dry sausage$few$]::text[], $few$reheat before eating$few$, $few$okay_if_prepared$few$::public.safety_verdict, $few$Hot dogs, luncheon meats, cold cuts, and other deli-style meats may contain Listeria unless reheated.$few$, $few$Reheat until steaming hot or 165°F (74°C).$few$, $few$FoodSafety.gov: People at Risk: Pregnant Women$few$, $few$https://www.foodsafety.gov/risk/pregnant$few$);
insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$0ada7a99-225f-597f-83d1-3c5ec399bd5a$few$, $few$smoked-seafood$few$, $few$Refrigerated smoked seafood$few$, array[$few$lox$few$,$few$nova$few$,$few$kippered$few$,$few$smoked salmon$few$]::text[], $few$refrigerated$few$, $few$okay_if_prepared$few$::public.safety_verdict, $few$Refrigerated smoked seafood can contain Listeria. Do not eat it unless it is canned, shelf-stable, or cooked in a dish that reaches 165°F (74°C).$few$, $few$Choose canned or shelf-stable smoked seafood, or cook it to 165°F (74°C).$few$, $few$FoodSafety.gov: People at Risk: Pregnant Women$few$, $few$https://www.foodsafety.gov/risk/pregnant$few$);
insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$be7f5517-64c2-5fef-a65d-b4136e162667$few$, $few$unpasteurized-juice$few$, $few$Unpasteurized juice$few$, array[$few$unpasteurized cider$few$,$few$fresh-squeezed juice$few$,$few$raw juice$few$]::text[], $few$unpasteurized$few$, $few$avoid$few$::public.safety_verdict, $few$Unpasteurized juice and cider, including fresh-squeezed juice, can contain E. coli and other germs.$few$, $few$Choose pasteurized juice, or boil unpasteurized juice or cider for at least 1 minute.$few$, $few$FoodSafety.gov: People at Risk: Pregnant Women$few$, $few$https://www.foodsafety.gov/risk/pregnant$few$);
insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$bb85cecc-ba86-52dd-9632-86030334be92$few$, $few$raw-milk$few$, $few$Raw milk$few$, array[$few$unpasteurized milk$few$]::text[], $few$unpasteurized$few$, $few$avoid$few$::public.safety_verdict, $few$Raw milk may contain Campylobacter, E. coli, Listeria, Salmonella, or the bacteria that cause tuberculosis.$few$, $few$Choose pasteurized milk.$few$, $few$FoodSafety.gov: People at Risk: Pregnant Women$few$, $few$https://www.foodsafety.gov/risk/pregnant$few$);
insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$601c35cb-6951-58bc-b669-fe0d514b5078$few$, $few$queso-fresco$few$, $few$Queso fresco$few$, array[$few$queso blanco$few$,$few$requeson$few$]::text[], $few$fresh soft cheese$few$, $few$avoid$few$::public.safety_verdict, $few$Avoid unheated queso fresco-type cheeses, whether the milk was pasteurized or not, and avoid any cheese made with raw milk.$few$, $few$Heat queso fresco-type cheese to 165°F or until steaming hot.$few$, $few$FoodSafety.gov: People at Risk: Pregnant Women$few$, $few$https://www.foodsafety.gov/risk/pregnant$few$);
insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$806b6885-d5ed-560c-87a5-5bfd62734728$few$, $few$raw-sprouts$few$, $few$Raw sprouts$few$, array[$few$alfalfa sprouts$few$,$few$clover sprouts$few$,$few$mung bean sprouts$few$,$few$radish sprouts$few$,$few$sprouts$few$]::text[], $few$raw$few$, $few$avoid$few$::public.safety_verdict, $few$Raw or undercooked sprouts may contain E. coli or Salmonella.$few$, $few$Cook sprouts thoroughly.$few$, $few$FoodSafety.gov: People at Risk: Pregnant Women$few$, $few$https://www.foodsafety.gov/risk/pregnant$few$);
insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$7e2c29ec-5e66-50e3-90f2-1ad8ebf66544$few$, $few$deli-salad$few$, $few$Premade deli salad$few$, array[$few$ham salad$few$,$few$chicken salad$few$,$few$seafood salad$few$,$few$tuna salad from the deli$few$]::text[], $few$premade$few$, $few$avoid$few$::public.safety_verdict, $few$Do not buy or eat premade ham salad, chicken salad, or seafood salad from a deli. They may contain Listeria.$few$, $few$Skip premade deli meat and seafood salads.$few$, $few$FoodSafety.gov: People at Risk: Pregnant Women$few$, $few$https://www.foodsafety.gov/risk/pregnant$few$);
insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$9e257359-a641-54a4-a833-13cabba2568d$few$, $few$raw-dough$few$, $few$Raw dough$few$, array[$few$raw batter$few$,$few$cookie dough$few$,$few$cake batter$few$]::text[], $few$uncooked$few$, $few$avoid$few$::public.safety_verdict, $few$Raw dough or batter can make you sick. Flour may contain E. coli, and raw eggs may contain Salmonella.$few$, $few$Bake or cook the batter thoroughly before eating.$few$, $few$FoodSafety.gov: People at Risk: Pregnant Women$few$, $few$https://www.foodsafety.gov/risk/pregnant$few$);
insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$865731e8-01f4-5d6c-aeec-fa328b984e6e$few$, $few$pate$few$, $few$Refrigerated pâté$few$, array[$few$pate$few$,$few$meat spread$few$,$few$liverwurst$few$]::text[], $few$refrigerated$few$, $few$avoid$few$::public.safety_verdict, $few$Refrigerated pâté or meat spreads from a deli or the refrigerated section can contain Listeria.$few$, $few$Choose pâté in a can, jar, or sealed pouch that does not need refrigeration before opening, then refrigerate it after opening.$few$, $few$FoodSafety.gov: People at Risk: Pregnant Women$few$, $few$https://www.foodsafety.gov/risk/pregnant$few$);
