insert into public.foods (id, slug, name, aliases, preparation, verdict, reason, safe_version, source_name, source_url) values ($few$f823c523-b8bf-52b2-911e-91f211242cf3$few$, $few$albacore-tuna$few$, $few$Albacore tuna$few$, array[$few$white tuna$few$]::text[], null, $few$limit$few$::public.safety_verdict, $few$FDA lists albacore and white tuna as a Good Choice. Eat one serving that week and no other fish. A serving in pregnancy is 4 ounces.$few$, $few$Have only one 4-ounce serving of albacore or white tuna in a week, and no other fish that week. Canned light tuna is a Best Choice.$few$, $few$FDA: Advice about Eating Fish$few$, $few$https://www.fda.gov/food/consumers/advice-about-eating-fish$few$);
insert into public.recipes (id, slug, title, description, meal, meals, servings, servings_label, prep_min, cook_min, total_min, inactive_time_note, total_cost, cost_is_approximate, cost_store, cost_checked_date, effort_tags, diet_tags, wic_friendly, stage, chef_tips, superfood_spotlight, nutrition_highlights, benefits, evidence_links, photo_url, reviewed_by, reviewed_date, safety_note, source_document) values ($few$74544db1-8d00-5727-89d9-5c3cdb72a700$few$, $few$blueberry-chia-overnight-oats$few$, $few$Blueberry Chia Overnight Oats$few$, $few$This make-ahead breakfast combines oats, chia seeds, milk, and blueberries for an inexpensive meal containing fiber, calcium, healthy fats, and complex carbohydrates.$few$, $few$breakfast$few$::public.meal_type, array[$few$breakfast$few$::public.meal_type], 2, null, 5, 0, 5, $few$Refrigerate overnight or for at least 4 hours.$few$, 2.60, false, null, null, array[$few$no-cook$few$::public.effort_tag,$few$make-ahead$few$::public.effort_tag], array[$few$vegetarian$few$::public.diet_tag,$few$gluten-free option$few$::public.diet_tag], null, 'both'::public.stage_type, array[$few$Frozen blueberries reduce cost and food waste.$few$,$few$Use fortified soy milk and maple syrup for a vegan version.$few$,$few$Choose certified gluten-free oats when necessary.$few$,$few$Walnuts are optional if keeping costs low.$few$]::text[], $few$Chia seeds provide fiber and plant-based omega-3 fatty acids.$few$, array[$few$Fiber$few$,$few$Calcium$few$,$few$Plant-based omega-3 fats$few$,$few$Complex carbohydrates$few$,$few$Antioxidant-rich fruit$few$]::text[], array[$few$Calcium helps support maternal bone health and fetal bone and tooth development.$few$,$few$Fiber supports digestive health, which can be especially helpful during pregnancy.$few$,$few$Chia provides alpha-linolenic acid, a plant omega-3 fatty acid.$few$,$few$Milk or fortified soy milk contributes protein and calcium to help meet increased nutrient needs.$few$]::text[], $few$[{"label": "NIH: Pregnancy Nutrition", "url": "https://ods.od.nih.gov/factsheets/Pregnancy-HealthProfessional/"}, {"label": "CDC: Maternal Diet & Breastfeeding", "url": "https://www.cdc.gov/breastfeeding-special-circumstances/hcp/diet-micronutrients/maternal-diet.html"}, {"label": "Harvard Nutrition Source: Chia Seeds", "url": "https://nutritionsource.hsph.harvard.edu/food-features/chia-seeds/"}, {"label": "Harvard Nutrition Source: Oats", "url": "https://nutritionsource.hsph.harvard.edu/food-features/oats/"}]$few$::jsonb, null, null, null, null, $few$25 recipes.pdf$few$);
