insert into public.recipes (id, slug, title, description, meal, meals, servings, servings_label, prep_min, cook_min, total_min, inactive_time_note, total_cost, cost_is_approximate, cost_store, cost_checked_date, effort_tags, diet_tags, wic_friendly, stage, chef_tips, superfood_spotlight, nutrition_highlights, benefits, evidence_links, photo_url, reviewed_by, reviewed_date, safety_note, source_document) values ($few$b91a27dd-183f-5246-8b1b-9e27f084a6c3$few$, $few$lemon-garlic-salmon-sweet-potato-broccoli$few$, $few$Lemon Garlic Salmon with Sweet Potato & Broccoli$few$, $few$A simple sheet-pan pescatarian meal combining salmon with sweet potato and broccoli.$few$, $few$lunch$few$::public.meal_type, array[$few$lunch$few$::public.meal_type,$few$dinner$few$::public.meal_type], 2, null, 10, 30, 40, null, 8.50, false, null, null, array[$few$sheet-pan$few$::public.effort_tag], array[$few$pescatarian$few$::public.diet_tag], null, 'both'::public.stage_type, array[$few$Frozen salmon and broccoli reduce food waste.$few$,$few$Choose salmon from FDA lower-mercury choices during pregnancy.$few$,$few$Substitute tilapia for a cheaper pescatarian version.$few$,$few$Replace salmon with calcium-set tofu for a vegetarian or vegan option.$few$]::text[], $few$Salmon provides high-quality protein and DHA/EPA omega-3 fatty acids.$few$, array[$few$Protein$few$,$few$DHA/EPA omega-3 fats$few$,$few$Vitamin D$few$,$few$Beta-carotene$few$,$few$Fiber$few$]::text[], array[$few$Fish provides DHA and EPA, which support fetal and infant brain development.$few$,$few$FDA identifies seafood as a source of omega-3 fats, iodine, choline, iron, vitamin D, and protein.$few$,$few$Sweet potato provides beta-carotene, which the body can convert to vitamin A.$few$,$few$Vitamin A is important for normal growth and development.$few$]::text[], $few$[{"label": "FDA: Advice About Eating Fish During Pregnancy & Breastfeeding", "url": "https://www.fda.gov/food/consumers/advice-about-eating-fish"}, {"label": "NIH: Pregnancy Nutrition", "url": "https://ods.od.nih.gov/factsheets/Pregnancy-HealthProfessional/"}, {"label": "Harvard Nutrition Source: Sweet Potatoes", "url": "https://nutritionsource.hsph.harvard.edu/food-features/sweet-potatoes/"}, {"label": "NIH: Vitamin A and Carotenoids", "url": "https://ods.od.nih.gov/factsheets/VitaminA-HealthProfessional/"}]$few$::jsonb, null, null, null, $few$Choose salmon from FDA lower-mercury choices during pregnancy.$few$, $few$25 recipes.pdf$few$);
