insert into public.recipes (id, slug, title, description, meal, meals, servings, servings_label, prep_min, cook_min, total_min, inactive_time_note, total_cost, cost_is_approximate, cost_store, cost_checked_date, effort_tags, diet_tags, wic_friendly, stage, chef_tips, superfood_spotlight, nutrition_highlights, benefits, evidence_links, photo_url, reviewed_by, reviewed_date, safety_note, source_document) values ($few$6bc898ba-00d1-5ed7-8894-8ce113b3c94e$few$, $few$spinach-egg-sweet-potato-breakfast-hash$few$, $few$Spinach, Egg & Sweet Potato Breakfast Hash$few$, $few$A quick, savory breakfast made with inexpensive eggs, sweet potato, and spinach. It provides protein, choline, folate, iron, and beta-carotene.$few$, $few$breakfast$few$::public.meal_type, array[$few$breakfast$few$::public.meal_type], 2, null, 5, 12, 17, null, 2.75, true, null, null, '{}'::public.effort_tag[], array[$few$vegetarian$few$::public.diet_tag], null, 'both'::public.stage_type, array[$few$Microwave the sweet potato first to shorten cooking time.$few$,$few$Frozen spinach works well and is often less expensive.$few$,$few$Eggs should be cooked thoroughly during pregnancy.$few$,$few$For a vegan version, replace eggs with crumbled calcium-set tofu.$few$]::text[], $few$Eggs are one of the richest commonly eaten food sources of choline.$few$, array[$few$Choline$few$,$few$Protein$few$,$few$Folate$few$,$few$Iron$few$,$few$Beta-carotene$few$,$few$Vitamin A precursors$few$]::text[], array[$few$Choline is an important pregnancy nutrient involved in fetal growth and central nervous system development.$few$,$few$Choline needs increase further during breastfeeding.$few$,$few$CDC specifically lists eggs among foods that provide choline.$few$,$few$Spinach contributes folate, while sweet potato provides beta-carotene.$few$]::text[], $few$[{"label": "NIH: Pregnancy Nutrition", "url": "https://ods.od.nih.gov/factsheets/Pregnancy-HealthProfessional/"}, {"label": "CDC: Maternal Diet & Breastfeeding", "url": "https://www.cdc.gov/breastfeeding-special-circumstances/hcp/diet-micronutrients/maternal-diet.html"}, {"label": "NIH: Choline", "url": "https://ods.od.nih.gov/factsheets/Choline-HealthProfessional/"}, {"label": "Harvard Nutrition Source: Sweet Potatoes", "url": "https://nutritionsource.hsph.harvard.edu/food-features/sweet-potatoes/"}]$few$::jsonb, null, null, null, $few$Eggs should be cooked thoroughly during pregnancy.$few$, $few$25 recipes.pdf$few$);
