insert into public.recipes (id, slug, title, description, meal, meals, servings, servings_label, prep_min, cook_min, total_min, inactive_time_note, total_cost, cost_is_approximate, cost_store, cost_checked_date, effort_tags, diet_tags, wic_friendly, stage, chef_tips, superfood_spotlight, nutrition_highlights, benefits, evidence_links, photo_url, reviewed_by, reviewed_date, safety_note, source_document) values ($few$3d6fcda7-3368-5639-a1ad-9cc1836b1337$few$, $few$apple-cinnamon-peanut-butter-overnight-oats$few$, $few$Apple Cinnamon Peanut Butter Overnight Oats$few$, $few$A budget-friendly make-ahead breakfast requiring no morning cooking. Oats, milk, peanut butter, chia, and apple provide carbohydrates, protein, fiber, calcium, and healthy fats.$few$, $few$breakfast$few$::public.meal_type, array[$few$breakfast$few$::public.meal_type], 2, null, 5, 0, 5, $few$Refrigerate overnight or for at least 4 hours.$few$, 2.20, true, null, null, array[$few$no-cook$few$::public.effort_tag,$few$make-ahead$few$::public.effort_tag], array[$few$vegetarian$few$::public.diet_tag,$few$gluten-free option$few$::public.diet_tag], null, 'both'::public.stage_type, array[$few$Use whichever inexpensive apple variety is available.$few$,$few$Use fortified soy milk and maple syrup for a vegan version.$few$,$few$Certified gluten-free oats can be used when needed.$few$,$few$Prepare several jars at once for meal prep.$few$]::text[], $few$Fortified milk or soy milk contributes calcium, while chia and peanut butter provide healthy fats.$few$, array[$few$Calcium$few$,$few$Fiber$few$,$few$Protein$few$,$few$Healthy fats$few$,$few$Complex carbohydrates$few$]::text[], array[$few$Calcium is important during pregnancy for strong bones and teeth.$few$,$few$Protein contributes to increased maternal nutritional needs.$few$,$few$Fiber supports digestion.$few$,$few$Breastfeeding increases overall energy requirements, making easy nutrient-dense breakfasts useful.$few$]::text[], $few$[{"label": "NIH: Pregnancy Nutrition", "url": "https://ods.od.nih.gov/factsheets/Pregnancy-HealthProfessional/"}, {"label": "CDC: Maternal Diet & Breastfeeding", "url": "https://www.cdc.gov/breastfeeding-special-circumstances/hcp/diet-micronutrients/maternal-diet.html"}, {"label": "Harvard Nutrition Source: Oats", "url": "https://nutritionsource.hsph.harvard.edu/food-features/oats/"}, {"label": "NIH: Calcium", "url": "https://ods.od.nih.gov/factsheets/Calcium-HealthProfessional/"}, {"label": "Harvard Nutrition Source: Eating Well on a Budget", "url": "https://nutritionsource.hsph.harvard.edu/strategies-nutrition-budget/"}]$few$::jsonb, null, null, null, null, $few$25 recipes.pdf$few$);
