insert into public.recipes (id, slug, title, description, meal, meals, servings, servings_label, prep_min, cook_min, total_min, inactive_time_note, total_cost, cost_is_approximate, cost_store, cost_checked_date, effort_tags, diet_tags, wic_friendly, stage, chef_tips, superfood_spotlight, nutrition_highlights, benefits, evidence_links, photo_url, reviewed_by, reviewed_date, safety_note, source_document) values ($few$1468c7a5-1089-5e5c-bcd3-78a40900944a$few$, $few$quick-sardine-white-bean-tomato-toast$few$, $few$Quick Sardine, White Bean & Tomato Toast$few$, $few$A quick pescatarian lunch combining inexpensive canned sardines, white beans, tomatoes, and whole-grain toast.$few$, $few$lunch$few$::public.meal_type, array[$few$lunch$few$::public.meal_type], 2, null, 5, 5, 10, null, 4.25, true, null, null, '{}'::public.effort_tag[], array[$few$pescatarian$few$::public.diet_tag,$few$gluten-free option$few$::public.diet_tag], null, 'both'::public.stage_type, array[$few$Canned sardines are shelf-stable and often less expensive than fresh fish.$few$,$few$FDA lists sardines among lower-mercury “Best Choices.”$few$,$few$Use gluten-free bread when necessary.$few$,$few$For a vegan version, leave off sardines and increase the beans to 2 cups.$few$]::text[], $few$Sardines provide protein, omega-3 fatty acids, vitamin D, calcium when the edible bones are included, and other seafood nutrients.$few$, array[$few$Protein$few$,$few$DHA/EPA omega-3 fats$few$,$few$Calcium$few$,$few$Vitamin D$few$,$few$Iron$few$,$few$Folate$few$,$few$Choline$few$]::text[], array[$few$FDA recommends 8–12 ounces per week of a variety of lower-mercury seafood during pregnancy and breastfeeding.$few$,$few$Fish provides omega-3 fats, protein, iodine, choline, iron, vitamin D, and other nutrients relevant to pregnancy and lactation.$few$,$few$White beans add iron, folate, fiber, and choline.$few$,$few$Sardines with edible bones can also contribute calcium.$few$]::text[], $few$[{"label": "FDA: Advice About Eating Fish", "url": "https://www.fda.gov/food/consumers/advice-about-eating-fish"}, {"label": "NIH: Pregnancy Nutrition", "url": "https://ods.od.nih.gov/factsheets/Pregnancy-HealthProfessional/"}, {"label": "NIH: Calcium", "url": "https://ods.od.nih.gov/factsheets/Calcium-HealthProfessional/"}, {"label": "Harvard Nutrition Source: Legumes and Pulses", "url": "https://nutritionsource.hsph.harvard.edu/legumes-pulses/"}]$few$::jsonb, null, null, null, $few$FDA lists sardines among lower-mercury “Best Choices.”$few$, $few$25 recipes.pdf$few$);
