insert into public.recipes (id, slug, title, description, meal, meals, servings, servings_label, prep_min, cook_min, total_min, inactive_time_note, total_cost, cost_is_approximate, cost_store, cost_checked_date, effort_tags, diet_tags, wic_friendly, stage, chef_tips, superfood_spotlight, nutrition_highlights, benefits, evidence_links, photo_url, reviewed_by, reviewed_date, safety_note, source_document) values ($few$17202505-5989-51a1-98dc-2e4787c3b9a8$few$, $few$one-pot-peanut-lentil-sweet-potato-stew$few$, $few$One-Pot Peanut Lentil & Sweet Potato Stew$few$, $few$A filling one-pot plant-based meal using inexpensive lentils, sweet potatoes, peanut butter, tomatoes, and spinach.$few$, $few$lunch$few$::public.meal_type, array[$few$lunch$few$::public.meal_type,$few$dinner$few$::public.meal_type], 4, null, 10, 25, 35, null, 4.75, true, null, null, array[$few$one-pot$few$::public.effort_tag], array[$few$vegetarian$few$::public.diet_tag,$few$vegan$few$::public.diet_tag,$few$gluten-free option$few$::public.diet_tag], null, 'both'::public.stage_type, array[$few$Red lentils cook quickly and require no soaking.$few$,$few$Frozen spinach keeps this inexpensive and convenient.$few$,$few$Use sunflower seed butter for a peanut-free version.$few$,$few$Serve alone or over rice if a higher-energy meal is needed.$few$,$few$The recipe is naturally vegan and gluten-free when all packaged ingredients are certified as needed.$few$]::text[], $few$Lentils provide folate, iron, plant protein, fiber, and choline, while sweet potatoes provide beta-carotene.$few$, array[$few$Folate$few$,$few$Iron$few$,$few$Plant protein$few$,$few$Choline$few$,$few$Fiber$few$,$few$Beta-carotene$few$,$few$Healthy fats$few$]::text[], array[$few$Folate supports healthy fetal development and cell division.$few$,$few$Iron needs increase substantially during pregnancy.$few$,$few$Lentils are among the foods CDC identifies as sources of choline, whose needs increase during breastfeeding.$few$,$few$Sweet potatoes provide beta-carotene, which the body can convert to vitamin A.$few$,$few$Peanut butter adds energy, plant protein, and unsaturated fats.$few$]::text[], $few$[{"label": "NIH: Pregnancy Nutrition", "url": "https://ods.od.nih.gov/factsheets/Pregnancy-HealthProfessional/"}, {"label": "CDC: Maternal Diet & Breastfeeding", "url": "https://www.cdc.gov/breastfeeding-special-circumstances/hcp/diet-micronutrients/maternal-diet.html"}, {"label": "Harvard Nutrition Source: Lentils", "url": "https://nutritionsource.hsph.harvard.edu/food-features/lentils/"}, {"label": "Harvard Nutrition Source: Sweet Potatoes", "url": "https://nutritionsource.hsph.harvard.edu/food-features/sweet-potatoes/"}, {"label": "NIH: Vitamin A and Carotenoids", "url": "https://ods.od.nih.gov/factsheets/VitaminA-HealthProfessional/"}]$few$::jsonb, null, null, null, null, $few$25 recipes.pdf$few$);
